B.add(486,'single','Докажите теорему Вариньона: середины сторон произвольного четырёхугольника являются вершинами параллелограмма.','MNPQ — параллелограмм; выпуклость исходного четырёхугольника не требуется.',[
 row('Какую вспомогательную линию провести?','Обозначим середины AB,BC,CD,DA через M,N,P,Q. Проведём диагональ AC.','Диагональ делит рассуждение на два треугольника.',47),
 row('Что дают средние линии двух треугольников?','В ABC отрезок MN параллелен AC и равен AC/2; в ADC отрезок QP также параллелен AC и равен AC/2.','Свойство средней линии, доказанное в задаче 484.',[48,49]),
 row('Как завершить доказательство?','MN ∥QP и MN =QP, поэтому MNPQ — параллелограмм. Доказательство работает и для невыпуклого простого четырёхугольника: оба нужных треугольника остаются невырожденными.','Признак параллелограмма по одной паре сторон.',49)],p,v,[f,f,f],checks=[par('M','N','Q','P'),equal(('M','N'),('Q','P'))],cases=[(q,w,'Невыпуклый четырёхугольник',3,[par('M','N','Q','P'),equal(('M','N'),('Q','P'))])])
